using HakutaiKagami.Core.Contracts;
using Xunit;
namespace HakutaiKagami.Tests;
public sealed class TruceSuccessionTests
{
    static readonly EntityId Home=new("site:kofu"),Owner=new("org:takeda"),Other=new("org:oda"),Old=new("person:shingen"),Heir=HistoricalHouseholdCatalog.Edition.People.Single().Id;
    static WorldSession Start()=>new(NewGameWorld.Create(NewGameWorld.Scenario(HistoricalStartCatalog.Current),[],Old.Value,42,historicalCatalog:HistoricalStartCatalog.Current,inspectionPolicy:LocalInspectionFindings.Policy,workPolicy:WorkFollowup.Policy,worldArmyPolicy:NpcArmies.CompactCombatPolicy,economyPolicy:HouseSuccession.Policy,trucePolicy:TruceNegotiations.Policy));
    static void Good(CommandResult r)=>Assert.True(r.Code==ResultCode.Accepted,r.VisibleReason);
    static void At(WorldSession s,long t){while(s.Seconds<t){var before=s.Seconds;s.SetPaused(false);s.AdvanceTo(t,100000);Assert.True(s.Seconds>before);}}
    static void Succeed(WorldSession s){var id=new EntityId("request:truce-successor/"+s.Revision);Good(s.ManageHouseSuccession(new(id,HouseSuccessionAction.Nominate,Owner,Heir),Old,s.Revision));Good(s.ManageHouseSuccession(new(new("request:truce-successor-confirm/"+s.Revision),HouseSuccessionAction.Confirm,Owner,Original:id),Old,s.Revision));At(s,s.Seconds+1);}
    static long Arrival(WorldSession s,TrucePaper p)=>s.DiagnosticSnapshot().Couriers!.Missions.Single(c=>s.DiagnosticSnapshot().Messaging.Attempts.Any(a=>a.Id==c.Attempt&&a.MessageId==p.Message)).ReadyAt;
    static TrucePaper Formation(WorldSession s,bool open=true){Good(s.NegotiateTruce(new(new("request:old-head-truce"),TruceAction.Propose,Owner,Other,Days:30),Old,s.Revision));var offer=s.DiagnosticSnapshot().Truces!.Papers.Single();At(s,Arrival(s,offer)+1);var accept=s.DiagnosticSnapshot().Truces!.Papers.Single(p=>p.Input.Action==TruceAction.Accept);At(s,Arrival(s,accept));if(open){Good(s.Open(Old,new(accept.Message),s.Revision));var confirm=s.DiagnosticSnapshot().Truces!.Papers.Single(p=>p.Input.Action==TruceAction.Confirm);At(s,Arrival(s,confirm));}return accept;}
    static TruceSuccessionInput Read(WorldSession s,EntityId acceptance)=>new(new("request:truce-read/"+s.Revision),Owner,acceptance);
    [Fact]public void KnownFormedOrganizationAgreementKeepsTermsAndOldPapers(){var s=Start();var p=Formation(s);Succeed(s);var before=s.DiagnosticSnapshot();Assert.False(TruceNegotiations.WillNotInitiate(before,Owner,Other,s.Seconds,s.Revision));var i=Read(s,p.Input.Id);Assert.Contains(s.TruceSuccessionView(),c=>c.Acceptance==p.Input.Id&&c.CanRead);Good(s.ReadInheritedTruce(i,Old,s.Revision));var w=s.DiagnosticSnapshot();Assert.True(TruceNegotiations.WillNotInitiate(w,Owner,Other,s.Seconds,s.Revision));Assert.Contains(TruceNegotiations.Known(w,Heir),f=>f.Acceptance==p.Input.Id&&f.Terms==p.Terms);Assert.Equal(ContractJson.Write(before.Truces),ContractJson.Write(w.Truces));Assert.Equal(ContractJson.Write(before.ResourceLots),ContractJson.Write(w.ResourceLots));Assert.Equal(ContractJson.Write(before.Units),ContractJson.Write(w.Units));Assert.Equal(Old,w.Truces!.Papers.Single(q=>q.Input.Id==p.Input.Id).Recipient);new WorldSession(w);}
    [Fact]public void UnknownOldAcceptanceCannotBeShownAndOpeningAfterRetirementDoesNotActWithOldAuthority(){var s=Start();var p=Formation(s,false);Succeed(s);Assert.Empty(s.TruceSuccessionView());Assert.Equal(ResultCode.NotAvailable,s.ReadInheritedTruce(Read(s,p.Input.Id),Old,s.Revision).Code);Good(s.Open(Old,new(p.Message),s.Revision));Assert.DoesNotContain(s.DiagnosticSnapshot().Truces!.Papers,q=>q.Input.Action==TruceAction.Confirm);Good(s.ReadInheritedTruce(Read(s,p.Input.Id),Old,s.Revision));Assert.True(TruceNegotiations.WillNotInitiate(s.DiagnosticSnapshot(),Owner,Other,s.Seconds,s.Revision));Assert.False(TruceNegotiations.WillNotInitiate(s.DiagnosticSnapshot(),Other,Owner,s.Seconds,s.Revision));At(s,s.Seconds+10);new WorldSession(s.DiagnosticSnapshot());}
    [Fact]public void UnformedProposalAndUnchangedHeadDoNotCreateInheritance(){var s=Start();Good(s.NegotiateTruce(new(new("request:pending-old-truce"),TruceAction.Propose,Owner,Other,Days:30),Old,s.Revision));Assert.Equal(ResultCode.NotAvailable,s.ReadInheritedTruce(Read(s,new("request:pending-old-truce")),Old,s.Revision).Code);Succeed(s);Assert.Empty(s.TruceSuccessionView());Assert.Equal(ResultCode.NotAvailable,s.ReadInheritedTruce(Read(s,new("request:pending-old-truce")),Old,s.Revision).Code);}
    [Fact]public void RepeatedStaleWrongActorAndConflictingReadsCannotDuplicateKnowledge(){var s=Start();var p=Formation(s);Succeed(s);var i=Read(s,p.Input.Id);Assert.Equal(ResultCode.NotAvailable,s.ReadInheritedTruce(i,Heir,s.Revision).Code);Assert.Equal(ResultCode.StateChanged,s.ReadInheritedTruce(i,Old,s.Revision-1).Code);Good(s.ReadInheritedTruce(i,Old,s.Revision));Assert.Equal(ResultCode.AlreadyAccepted,s.ReadInheritedTruce(i,Old,0).Code);Assert.Equal(ResultCode.IdPayloadConflict,s.ReadInheritedTruce(i with{Owner=Other},Old,s.Revision).Code);Assert.Equal(ResultCode.NotAvailable,s.ReadInheritedTruce(Read(s,p.Input.Id),Old,s.Revision).Code);Assert.Single(s.DiagnosticSnapshot().TruceInheritance!.Entries);}
    [Fact]public void ExpiryIsNotExtendedBySuccessionReading(){var s=Start();var p=Formation(s);Succeed(s);Good(s.ReadInheritedTruce(Read(s,p.Input.Id),Old,s.Revision));At(s,p.Terms.Until);Assert.False(TruceNegotiations.WillNotInitiate(s.DiagnosticSnapshot(),Owner,Other,s.Seconds,s.Revision));Assert.Equal(p.Terms,s.DiagnosticSnapshot().Truces!.Formations.Single().Terms);Assert.Equal(ResultCode.NotAvailable,s.ReadInheritedTruce(Read(s,p.Input.Id),Old,s.Revision).Code);}
    [Fact]public void RemoteOldRepresentativeCannotRevealTheTreatyByReading(){var s=Start();var p=Formation(s);Succeed(s);Good(s.Submit(TravelWorld.Move(s.DiagnosticSnapshot(),"request:remote-truce-old-head","castle"),s.Revision));At(s,s.Seconds+2);Assert.Empty(s.TruceSuccessionView());Assert.Equal(ResultCode.NotAvailable,s.ReadInheritedTruce(Read(s,p.Input.Id),Old,s.Revision).Code);Assert.Empty(TruceNegotiations.Known(s.DiagnosticSnapshot(),Heir));}
    [Theory][InlineData(0)][InlineData(1)][InlineData(2)][InlineData(3)]public void ForgedKnowledgeOrPartiesDoNotLoad(int n){var s=Start();var p=Formation(s);Succeed(s);Good(s.ReadInheritedTruce(Read(s,p.Input.Id),Old,s.Revision));var w=s.DiagnosticSnapshot();var e=w.TruceInheritance!.Entries.Single();w.TruceInheritance.Entries[0]=n switch{0=>e with{Previous=Heir},1=>e with{Successor=Old},2=>e with{Site=new("site:castle")},_=>e with{Input=e.Input with{Acceptance=new("request:not-an-agreement")}}};Assert.Throws<InvalidDataException>(()=>new WorldSession(w));}
    [Fact]public void HistoricalKnowledgeDoesNotBorrowALaterSameSecondReading(){var s=Start();var p=Formation(s);Succeed(s);long before=s.Revision;Good(s.ReadInheritedTruce(Read(s,p.Input.Id),Old,s.Revision));var w=s.DiagnosticSnapshot();Assert.Empty(TruceNegotiations.Known(w,Heir,s.Seconds,before));Assert.Single(TruceNegotiations.Known(w,Heir));}
    [Theory][InlineData(0)][InlineData(1)][InlineData(2)][InlineData(3)]public void ActualGenerationRecoveryAndFutureKeepDiplomaticKnowledge(int phase){var s=Start();var p=Formation(s,phase!=0);if(phase>0)Succeed(s);if(phase>=2)Good(s.ReadInheritedTruce(Read(s,p.Input.Id),Old,s.Revision));if(phase==3){Good(s.Submit(TravelWorld.Move(s.DiagnosticSnapshot(),"request:saved-truce-away","castle"),s.Revision));At(s,s.Seconds+2);}s.SetPaused(true);var w=s.DiagnosticSnapshot();var store=new GenerationSaveStore(Path.Combine(Path.GetTempPath(),"truce-inheritance-"+Guid.NewGuid().ToString("N")),w.Definitions);Assert.True(store.Save(s,"treaty",w.WorldId).Published);var host=new WorldSessionHost(Start());Assert.Equal(ResultCode.Accepted,host.CommitLoad(store.Prepare("treaty"),host.Current,host.Current.Revision));var b=host.Current;Assert.Equal(ContractJson.Write(w),ContractJson.Write(b.DiagnosticSnapshot()));Assert.Equal(ContractJson.Write(s.TruceSuccessionView()),ContractJson.Write(b.TruceSuccessionView()));var dir=Environment.GetEnvironmentVariable("HAKUTAI_WORLD_CLASH_QA_DIR");if(!string.IsNullOrEmpty(dir)){File.WriteAllBytes(Path.Combine(dir,$"truce-inheritance-{phase}.before.json"),ContractJson.Write(w));File.WriteAllBytes(Path.Combine(dir,$"truce-inheritance-{phase}.restored.json"),ContractJson.Write(b.DiagnosticSnapshot()));}foreach(var x in new[]{s,b})At(x,x.Seconds+10);Assert.Equal(ContractJson.Write(s.DiagnosticSnapshot()),ContractJson.Write(b.DiagnosticSnapshot()));}

    [Theory][InlineData("Previous")][InlineData("Site")][InlineData("Revision")]public void OptionalExtensionDoesNotRelaxRequiredHandoverFields(string name){var s=Start();var p=Formation(s);Succeed(s);Good(s.ReadInheritedTruce(Read(s,p.Input.Id),Old,s.Revision));var node=System.Text.Json.Nodes.JsonNode.Parse(ContractJson.Write(s.DiagnosticSnapshot()))!;node["TruceInheritance"]!["Entries"]![0]!.AsObject().Remove(name);Assert.Throws<InvalidDataException>(()=>ContractJson.Read<ContractWorld>(System.Text.Encoding.UTF8.GetBytes(node.ToJsonString())));}
    [Fact]public void LegacyWorldDoesNotAcquireDiplomaticKnowledgeOnLoad(){var s=TruceNegotiationTests.Start(false);var before=ContractJson.Write(s.DiagnosticSnapshot());Assert.DoesNotContain("TruceInheritance",System.Text.Encoding.UTF8.GetString(before));Assert.Empty(s.TruceSuccessionView());Assert.Equal(ResultCode.NotAvailable,s.ReadInheritedTruce(new(new("request:legacy-truce-inherit"),Owner,new("request:missing")),s.PlayerControl,s.Revision).Code);Assert.Equal(before,ContractJson.Write(s.DiagnosticSnapshot()));Assert.Equal(before,ContractJson.Write(new WorldSession(ContractJson.Read<ContractWorld>(before)).DiagnosticSnapshot()));}
    [Fact]public void ExistingProposalIdCannotBecomeHandoverId(){var s=Start();var p=Formation(s);Succeed(s);Assert.Equal(ResultCode.IdPayloadConflict,s.ReadInheritedTruce(new(new("request:old-head-truce"),Owner,p.Input.Id),Old,s.Revision).Code);Assert.Null(s.DiagnosticSnapshot().TruceInheritance);}
}
